<?php require_once __DIR__ . '/../../includes/layout.php'; require_role(['Teacher','Admin']); render_header('At-Risk Students'); ?><div class="page-title"><div><h1>At-Risk Students</h1><p>Students detected by AI predictive analytics.</p></div></div><div class="panel"><table class="table"><thead><tr><th>Student</th><th>Attendance</th><th>GPA</th><th>Risk</th><th>Recommended Action</th></tr></thead><tbody><?php foreach(rows("SELECT s.*,u.full_name FROM students s JOIN users u ON u.id=s.user_id WHERE s.risk_level IN ('High','Medium') ORDER BY CASE s.risk_level WHEN 'High' THEN 1 ELSE 2 END") as $s): ?><tr><td><?= e($s['student_no'].' - '.$s['full_name']) ?></td><td><?= e($s['attendance_rate']) ?>%</td><td><?= e($s['gpa']) ?></td><td><span class="badge-soft risk-<?= e($s['risk_level']) ?>"><?= e($s['risk_level']) ?></span></td><td><?= $s['risk_level']==='High'?'Schedule counseling and parent conference.':'Monitor weekly and provide intervention.' ?></td></tr><?php endforeach; ?></tbody></table></div><?php render_footer(); ?>
